product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
vehicle_info = {}
for rec in capacity_records:
    v = rec['values']
    vid = str(v['VehicleID'])
    vehicle_info[vid] = {'VehicleType': v['VehicleType'], 'Capacity': int(v['Capacity'])}
benefit_by_type = {}
for rec in product_records:
    v = rec['values']
    benefit_by_type[v['ProductName']] = int(v['Value'])
benefit_by_id = {}
for (vid, info) in vehicle_info.items():
    vt = info['VehicleType']
    if vt not in benefit_by_type:
        raise ValueError(f'Missing benefit for VehicleType {vt}')
    benefit_by_id[vid] = benefit_by_type[vt]
for vid in vehicle_info:
    if vid not in benefit_by_id:
        raise ValueError(f'Missing benefit for VehicleID {vid}')
    if 'Capacity' not in vehicle_info[vid]:
        raise ValueError(f'Missing capacity for VehicleID {vid}')
vehicle_ids = sorted(vehicle_info.keys(), key=lambda x: int(x))
capacity = {vid: vehicle_info[vid]['Capacity'] for vid in vehicle_ids}
benefit = {vid: benefit_by_id[vid] for vid in vehicle_ids}
total_capacity = sum((capacity[vid] for vid in vehicle_ids))
m = gp.Model('NewCarSalesInNorway')
x_vars = m.addVars(vehicle_ids, lb=0, ub=[capacity[vid] for vid in vehicle_ids], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit[vid] * x_vars[vid] for vid in vehicle_ids)), GRB.MAXIMIZE)
m.addConstrs((x_vars[vid] <= capacity[vid] for vid in vehicle_ids), name='')
m.addConstr(gp.quicksum((x_vars[vid] for vid in vehicle_ids)) <= total_capacity, name='total_cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for vid in vehicle_ids:
        print(f'x[{vid}]: {x_vars[vid].X}')
else:
    print(f'Solver status: {m.Status}')
